unsigned process_flac_audio_data(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_processed = 0;
    unsigned decoded_pos = 0;
    unsigned remaining = len;

    if (psf == NULL || len == 0)
        return 0;

    while (remaining > 0 && psf->decoder_state == SF_CODEC_OK) {
        if (psf->decoded_data != NULL && psf->decoded_length > 0) {
            unsigned copy_amount = SF_MIN(remaining, psf->decoded_length);
            memcpy(psf->output_buffer + bytes_processed, psf->decoded_data + decoded_pos, copy_amount);
            bytes_processed += copy_amount;
            remaining -= copy_amount;
            decoded_pos += copy_amount;

            if (decoded_pos >= psf->decoded_length) {
                psf->decoded_data = NULL;
                psf->decoded_length = 0;
            }
        }

        if (remaining > 0) {
            unsigned result = flac_decoder_read(psf, remaining);
            if (result == 0 || psf->decoder_state != SF_CODEC_OK) {
                break;
            }

            bytes_processed += result;
            remaining -= result;
        }
    }

    if (psf->decoder_state != SF_CODEC_OK) {
        sf_log_printf("FLAC decoder error: %s\n", flac_state_to_string(psf->decoder_state));
        psf->frame = NULL;
    }

    return bytes_processed;
}

unsigned flac_decode_loop_audio_data(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_processed = 0;
    unsigned position = 0;
    unsigned total_length = len;

    if (psf == NULL || len == 0)
        return 0;

    while (position < total_length) {
        if (psf->flac_decoder_state == FLAC_DECODER_ERROR) {
            sf_log_printf(SF_LOG_ERROR, "FLAC decoder encountered an error state.\n");
            psf->frame = NULL;
            break;
        }

        if (psf->flac_decoder_state == FLAC_DECODER_EOF) {
            sf_log_printf(SF_LOG_INFO, "Reached end of FLAC stream.\n");
            psf->frame = NULL;
            break;
        }

        if (psf->decoded_buffer_size > 0) {
            unsigned bytes_to_copy = SF_MIN(psf->decoded_buffer_size, total_length - position);
            memcpy(psf->output_buffer + position, psf->decoded_buffer, bytes_to_copy);
            position += bytes_to_copy;
            psf->decoded_buffer_size = 0;
            continue;
        }

        // Simulate decode call for the next chunk
        unsigned decoded_bytes = flac_decoder_read(psf, psf->output_buffer + position, total_length - position);
        if (decoded_bytes == 0) {
            if (psf->flac_decoder_state != FLAC_DECODER_EOF) {
                sf_log_printf(SF_LOG_ERROR, "FLAC decoder returned zero bytes with non-EOF state: %d.\n", psf->flac_decoder_state);
                psf->frame = NULL;
            }
            break;
        }

        position += decoded_bytes;
        bytes_processed += decoded_bytes;
    }

    return bytes_processed;
}

unsigned flac_decoder_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_processed = 0;
    unsigned pos = 0;
    unsigned available = 0;

    if (psf == NULL || len == 0)
        return 0;

    if (psf->flac_decoder == NULL)
        return 0;

    if (psf->flac_decoder->decoded_buffer != NULL && psf->flac_decoder->decoded_length > 0) {
        available = psf->flac_decoder->decoded_length;
        bytes_processed = (available < len) ? available : len;
        pos = bytes_processed;
        len -= bytes_processed;
        psf->flac_decoder->decoded_length -= pos;
        memmove(psf->flac_decoder->decoded_buffer, psf->flac_decoder->decoded_buffer + pos,
                psf->flac_decoder->decoded_length);
    }

    while (len > 0 && psf->flac_decoder->state == FLAC__STREAM_DECODER_OK) {
        unsigned bytes_read = 0;

        if (psf->flac_decoder->read_callback(psf->flac_decoder, psf->flac_decoder->input_buffer, len, &bytes_read) != 0) {
            break;
        }

        if (bytes_read == 0)
            break;

        if (psf->flac_decoder->decode_callback(psf->flac_decoder, psf->flac_decoder->input_buffer, bytes_read) != 0)
            break;

        bytes_processed += bytes_read;
        len -= bytes_read;
    }

    if (psf->flac_decoder->state != FLAC__STREAM_DECODER_OK) {
        switch (psf->flac_decoder->state) {
        case FLAC__STREAM_DECODER_EOS:
            sf_log(psf, SF_LOG_INFO, "FLAC decoder reached end of stream.");
            break;
        case FLAC__STREAM_DECODER_ABORTED:
            sf_log(psf, SF_LOG_ERROR, "FLAC decoding was aborted.");
            break;
        case FLAC__STREAM_DECODER_MEMORY_ALLOCATION_ERROR:
            sf_log(psf, SF_LOG_ERROR, "FLAC decoder memory allocation error.");
            break;
        default:
            sf_log(psf, SF_LOG_ERROR, "FLAC decoding error.");
            break;
        }

        psf->flac_decoder->frame = NULL;
    }

    return bytes_processed;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned total_read = 0;
    SF_INFO *info = &psf->sf.info;
    FLAC__StreamDecoder *decoder = psf->decoder;
    FLAC__StreamDecoderState decoder_state;

    if (psf->frame_buffer && psf->frame_buffer_used > 0) {
        unsigned copy = SF_MIN(len, psf->frame_buffer_used);
        memcpy(psf->frame_buffer + total_read, psf->frame_buffer, copy * info->channels * sizeof(short));
        total_read += copy;
        len -= copy;
        psf->frame_buffer_used -= copy;
        memmove(psf->frame_buffer, psf->frame_buffer + copy, psf->frame_buffer_used * info->channels * sizeof(short));
    }

    while (len > 0 && FLAC__stream_decoder_get_state(decoder) == FLAC__STREAM_DECODER_CONTINUE) {
        unsigned to_read = SF_MIN(len, 4096);
        unsigned samples = 0;

        FLAC__StreamDecoderState state = FLAC__stream_decoder_get_state(decoder);
        if (state != FLAC__STREAM_DECODER_CONTINUE) {
            break;
        }

        FLAC__bool ok = FLAC__stream_decoder_read(decoder, (FLAC__int32 **)&psf->frame_buffer + total_read, &samples);
        if (!ok || samples == 0) {
            break;
        }

        total_read += samples;
        len -= samples;
    }

    decoder_state = FLAC__stream_decoder_get_state(decoder);
    if (decoder_state != FLAC__STREAM_DECODER_CONTINUE && decoder_state != FLAC__STREAM_DECODER_SEARCH_FOR_METADATA && decoder_state != FLAC__STREAM_DECODER_READ_HEADER) {
        psf_log_printf(psf, "FLAC decoder state error: %s\n", FLAC__StreamDecoderStateString[decoder_state]);
        psf->frame = NULL;
    }

    return total_read;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_processed = 0;
    unsigned bytes_to_copy = 0;
    unsigned bytes_remaining = len;

    if (psf == NULL)
        return 0;

    if (psf->flacDecoder == NULL)
        return 0;

    if (psf->frame != NULL) {
        bytes_to_copy = psf->frame->bytes_decoded;
        if (bytes_to_copy > bytes_remaining)
            bytes_to_copy = bytes_remaining;

        if (bytes_to_copy > 0) {
            if (psf->write_function(psf, psf->frame->data, bytes_to_copy) != SF_ERR_NONE)
                return bytes_processed;

            bytes_processed += bytes_to_copy;
            bytes_remaining -= bytes_to_copy;
            psf->frame->bytes_decoded -= bytes_to_copy;
            memmove(psf->frame->data, psf->frame->data + bytes_to_copy, psf->frame->bytes_decoded);
        }
    }

    while (bytes_remaining > 0) {
        unsigned bytes_decoded = flac_decoder_decode(psf->flacDecoder, bytes_remaining);

        if (bytes_decoded == 0) {
            if (flac_decoder_get_state(psf->flacDecoder) == FLAC_DECODER_STATE_ERROR ||
                flac_decoder_get_state(psf->flacDecoder) == FLAC_DECODER_STATE_EOF)
                break;

            continue;
        }

        if (psf->write_function(psf, psf->frame->data, bytes_decoded) != SF_ERR_NONE)
            break;

        bytes_processed += bytes_decoded;
        bytes_remaining -= bytes_decoded;
    }

    if (flac_decoder_get_state(psf->flacDecoder) == FLAC_DECODER_STATE_ERROR ||
        flac_decoder_get_state(psf->flacDecoder) == FLAC_DECODER_STATE_EOF) {
        psf_log_printf(psf, "FLAC decoder state: %d\n", flac_decoder_get_state(psf->flacDecoder));
        psf->frame = NULL;
    }

    return bytes_processed;
}
